import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"33、【遁】 艮下乾上","description":"周易集注 - 33、【遁】 艮下乾上","frontmatter":{"title":"33、【遁】 艮下乾上","description":"周易集注 - 33、【遁】 艮下乾上"},"headers":[],"relativePath":"zh/classics/jizhu/037.md","filePath":"zh/classics/jizhu/037.md"}'),l={name:"zh/classics/jizhu/037.md"};function h(t,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_33、【遁】-艮下乾上" tabindex="-1">33、【遁】 艮下乾上 <a class="header-anchor" href="#_33、【遁】-艮下乾上" aria-label="Permalink to “33、【遁】 艮下乾上”">​</a></h1><p>遁者，退避也，六月之卦也。不言退而曰遁者，退止有退后之义，无避祸之义，所以不言退也。为卦天下有山，山虽高，其性本止。天之阳，性上进，违避而去，故有遁去之义。且二阴生于下，阴渐长，小人渐盛，君子退而避之，故为遁也。《序卦》“恒者久也，物不可以久居其所”，久则变，变则去，此理之常，所以次恒。</p><p>亨为君子言也。君子能遁，则身虽遁而道亨。小者，阴柔之小人也。指下二阴也。利贞者，小者利于正，而不害君子也。若害君子，小人亦不利也。</p><p>《彖》曰：遁亨，遁而亨也。刚当位而应，与时行也。小利贞，浸而长也。遁之时义大矣哉!浸居鸩反</p><p>以九五一爻释亨，以下二阴爻释利贞而赞之。遁而亨者，惟遁乃亨，见其不可不遁也。刚指五，当位者，当中正之位。而应者，下与六二相应也。时行，言顺时而行。身虽在位，而心则遁，此所以谓之时行也。九五，有中正之德，六二能承顺之，似亦可以不必于遁。然二阴浸而长，时不可不遁，知时之当遁，与时偕行，此其所以亨也。浸者渐也，浸而长，其势必至于害君子，故戒以利贞。时义大者，阴虽浸长，尚未盛大，且九五与二相应，其阳渐消之意，皆人之所未见而忽略者。是以茍且流连，而不能决去也。当此之时，使不审时度势，则不知遁。若眷恋禄位，又不能遁。惟有明哲保身之智，又有介石见几之勇，方能鸿冥凤举，所以叹其时义之大。汉元成之时，弘恭石显得志于内，而萧望之刘向朱云皆得巨祸。桓灵之际，曹节王甫得志于内，而李膺陈蕃窦武皆被诛戮，均不知遁之时义者也。易中大矣哉有二，有赞美其所系之大者，豫革之类是也;有称叹其所处之难者，大过遁之类是也。</p><h3 id="《象》曰-天下有山-遁-君子以远小人-不恶而严。远袁万反" tabindex="-1">《象》曰：天下有山，遁，君子以远小人，不恶而严。远袁万反 <a class="header-anchor" href="#《象》曰-天下有山-遁-君子以远小人-不恶而严。远袁万反" aria-label="Permalink to “《象》曰：天下有山，遁，君子以远小人，不恶而严。远袁万反”">​</a></h3><p>恶者，恶声厉色，疾之已甚也。严者，以礼律身，无可议之隙，而凛然不可犯也。不恶者待彼之礼，严者守己之节。天下有山，天虽无意于绝山，而山自不能以及乎天，遁之象也。故君子以远小人，不恶而严。曰不恶而严则君子无心于远小人，而小人自远，与天之无心于远山，而山自绝于天者同矣。远小人，艮止象。不恶而严，乾刚象。</p><p>初六，遁尾厉，勿用有攸往。</p><p>遁者，居当遁之时也。尾者初也，因在下，故曰尾。厉者天下贤人君子皆以遁去，时何时也?岂不危厉。往者，往而遁去也。本卦遁，乃阳刚与阴，不相干涉，故不可往，且初在下，无位，又阴柔，所居不正，无德无位。无德则无声闻，不过凡民耳。与遁去之贤人君子不同，遁之何益?</p><p>初六居下当遁之时，亦危厉矣。但时虽危厉，而当遁者非初之人，故教占者勿用遁去，但晦处以俟时可也。</p><h3 id="《象》曰-遁尾之厉-不往何灾也" tabindex="-1">《象》曰：遁尾之厉，不往何灾也? <a class="header-anchor" href="#《象》曰-遁尾之厉-不往何灾也" aria-label="Permalink to “《象》曰：遁尾之厉，不往何灾也?”">​</a></h3><p>不遁有何灾咎，所以勿用有攸往。</p><p>六二，执之用黄牛之革，莫之胜说。胜音升，说音脱</p><p>执者执缚也。艮性止，执之象也。黄中色，指二。应爻错坤，牛之象也。胜者任也，脱者解脱也。能胜其脱，欲脱即脱矣。莫之胜脱者，不能脱也。言执缚之以黄牛之皮，与九五相交之志坚固不可脱也。本卦遁者乃阳，初与二阴爻皆未遁，故此爻不言遁字。</p><p>二阴浸长，近于上体之四阳*，已凌迫于阳矣。然二与五为正应，二以中正顺应乎五，五以中正亲合乎二，正所谓刚当位而应，不凌迫乎阳，可知矣。故有执之用黄牛之革，莫之胜说之象。占者是时亦当如此也。</p><ul><li>原文作“阴”，为“阳”之误。</li></ul><h3 id="《象》曰-执用黄牛-固志也。" tabindex="-1">《象》曰：执用黄牛，固志也。 <a class="header-anchor" href="#《象》曰-执用黄牛-固志也。" aria-label="Permalink to “《象》曰：执用黄牛，固志也。”">​</a></h3><p>坚固其二五中正相合之志也。</p><p>九三，系遁，有疾厉，畜臣妾吉。</p><p>系者，心维系而眷恋也。高祖有疾，手敕惠帝曰：“吾得疾随困，以如意母子相累，其馀诸儿皆足自立，哀此儿犹小也。”曹瞒临死持姬女而指季豹以示四子曰：“以累汝。”因泣下。此皆所谓系也。中爻为巽，巽为绳，系之象也。系遁者，怀禄徇私，隐忍而不去也。疾者，利欲为缠魔，困苦之疾也。厉者祸伏于此而危厉也，臣者仆也，妾者女子也，指下二阴也，乃三所系恋之类也。盖臣妾也，宫室也，利禄也，凡不出于天理之公，而出于人欲之私者，皆阴之类也，皆人之所系恋者也。本卦止言臣妾者，因二阴居下位故也。畜者止也，与剥卦顺而止之同，止之使制于阳而不陵上也。艮畜止象，又为阍寺，臣之象，又错兑，妾之象。</p><p>九三当阴长凌阳之界，与初二二爻同体，下比于阴，故有当遁而系恋之象。既有所系，则不能遁矣，盖疾而为厉之道也。然艮性能止，惟刚正自守，畜止同体，在下二阴驭之以臣妾之正道，使制于阳，而不陵上，斯吉矣，故又教占者必如此。</p><h3 id="《象》曰-系遁之厉-有疾惫也-畜臣妾吉-不可大事也。" tabindex="-1">《象》曰：系遁之厉，有疾惫也;畜臣妾吉，不可大事也。 <a class="header-anchor" href="#《象》曰-系遁之厉-有疾惫也-畜臣妾吉-不可大事也。" aria-label="Permalink to “《象》曰：系遁之厉，有疾惫也;畜臣妾吉，不可大事也。”">​</a></h3><p>疾惫者，疲惫于私欲，困而危矣。不可大事者，出处去就，乃大丈夫之大事。知此大事，方知其遁。若畜止臣妾，不过以在我艮止之性，禁令之尔，乃小事也。九三系遁，能此小事，亦即吉矣，岂能决断其出处去就之大事哉。</p><p>九四，好遁，君子吉，小人否。好呼报反，否方有反</p><p>三比二，故曰系。四应初，故曰好。好者爱也，系者缚也，爱者必眷恋而缚，缚者因喜悦而爱，其实一也。好遁者，又好而又遁也。好者爵位利禄，爱慕之事也。遁者审时度势，见几之事也。好者四也，遁者九也。阳居阴位，阳可为君子，阴可为小人，故可好可遁也。所以圣人设小人之戒。否者不也。</p><p>九四以刚居柔，下应初六，故有好而不遁之象。然干体刚健，又有遁而不好之象。占者顾其人何如耳，若刚果之君子，则有以胜其人欲之私，止知其遁，不知其好，得以遂其洁身之美，故吉矣。若小人，则徇欲忘反，止知其好，不知其遁，遁岂所能哉，故在小人则否也。</p><h3 id="《象》曰-君子好遁-小人否也。" tabindex="-1">《象》曰：君子好遁，小人否也。 <a class="header-anchor" href="#《象》曰-君子好遁-小人否也。" aria-label="Permalink to “《象》曰：君子好遁，小人否也。”">​</a></h3><p>君子刚果，故好而知遁，必于其遁。小人阴柔，故好而不知遁，惟知其好矣。</p><p>九五，嘉遁，贞吉。</p><p>嘉遁者，嘉美乎六二也。当二阴浸长之时，二以艮体，执之以黄牛之革，不凌犯乎阳，其志可谓坚固矣。为君者，不嘉美以正其志，安能治遁，故贞吉。若人君，无逃遁之理。玄宗幸蜀，安得为嘉。</p><p>九五阳刚中正，有治遁之才者也。当天下贤人君子遁去之时，下应六二之中正，见六二之志固，乃褒嘉之，表正其志，以成其不害贤人君子之美，正而且吉之道也，故其象占如此。</p><h3 id="《象》曰-嘉遁贞吉-以正志也。" tabindex="-1">《象》曰：嘉遁贞吉，以正志也。 <a class="header-anchor" href="#《象》曰-嘉遁贞吉-以正志也。" aria-label="Permalink to “《象》曰：嘉遁贞吉，以正志也。”">​</a></h3><p>二之固志者，坚固其事上之志，臣道中正之心也。五之正志者，表正其臣下之志，君道中正之心也。二五小象皆同言志字，所以知五褒嘉乎二。</p><p>上九，肥遁，无不利。</p><p>肥者，疾惫之反。遁字从豚，故初六言尾，上九言肥，皆象豚也。以阳刚之贤，而居霄汉之上。睟面盎背，莫非道德之丰腴。手舞足蹈，一皆仁义之膏泽。心广体胖，何肥如之。无不利者，天子不得臣，诸侯不得友，尧虽则天，不屈饮犊之高。武既应人，终全孤竹之节。理乱不闻，宠辱不惊，何利如之。</p><p>诸爻皆疑二阴之浸长，心既有所疑而戚戚，则身亦随之而疾瘠矣，安能肥乎?惟上九，以阳刚而居卦外，去柔最远，无所系应，独无所疑，盖此心超然于物外者也，故有肥遁之象，占无不利可知矣。</p><h3 id="《象》曰-肥遁无不利-无所疑也。" tabindex="-1">《象》曰：肥遁无不利，无所疑也。 <a class="header-anchor" href="#《象》曰-肥遁无不利-无所疑也。" aria-label="Permalink to “《象》曰：肥遁无不利，无所疑也。”">​</a></h3><p>无所疑者，不疑二阴之浸长而消阳也。无所疑，所以逍遥物外，不至于愁苦而疾瘠。</p>',38)])])}const f=e(l,[["render",h]]);export{_ as __pageData,f as default};
